def test(nm, S_src='out'):
    inp=np.array(G[nm+' input']); out=np.array(G[nm+' output'])
    # build S from out row0 as cyclic seq over the whole width: find minimal p such that out[0]==roll(S,-k)? Just try direct tile of out[0] periodic: assume S = out[0][:p] tiled forward; then out[i,j] == S[(j + i) % p]? or S[(j-i)%p]
    r0=out[0].tolist(); W2=len(r0); best=None
    for p in range(2,W2+1):
